class RmodOperations(InvokeSshHandler):
    """
    Responsible for operations executed directly on RMODs using ssh command shell and FRMon shell.
    """

    def __init__(self):
        super().__init__()
        self._rmod_credentials = None

    @log_input_and_output
    def reconnect_session_and_repeat_operation_when_oserror(func):
        """
        Decorator which causes rmod operation repetition in case of ssh socket error exception 'OSError'.
        Additional warning log and 5sec sleep is performed before next function repetition.

        Usage example:

        @reconnect_session_and_repeat_operation_when_oserror
        def _connect_rmod_ssh(self, rmod_id, connection, slave_bts, sw_stream=None, nahka_node=None):
            pass
        """
        def wrapper(self, *args, **kwargs):
            try:
                return func(self, *args, **kwargs)
            except OSError as exc:
                log_warning(f"Operation will be repeated after ssh session reconnect due to OSError: {str(exc)}")
                super().reconnect_ssh_session()
                time.sleep(5)
            return func(self, *args, **kwargs)

        return wrapper

    @log_input_and_output
    def get_rmod_ssh_credentials(self, connection, rmod_id, sw_stream=None, custom_password=None):
        """
        Gets RMOD ssh credentials based on provided RMOD ID. Login and password are getting from init file,
        ip address and serial number are getting using admin Api.
        :param connection: AdminConnection object or if used, string name alias
        :type connection: AdminConnection or str
        :param rmod_id: RMOD configuration ID of particular radio module, e.g.: 1
        :type rmod_id: str or int
        :param sw_stream: Software stream of uploaded BTS package e.g.: '23R3', default equal as None means sw_stream
                          will be detected automatically
        :type sw_stream: str or None
        :param custom_password: if provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Default is None, which means password from init file will be used.
        :type custom_password: str or None
        :return: dict of RMOD credentials with following keys: 'ip', 'username', 'password' and 'sn',
                 e.g. : {'ip': '172.22.8.2', 'username': 'rfsw',
                         'password': 'KRG3dFggxxHw+s0z64U0AR22VyjfnXdHrAVdSv5jpc4=',
                         'sn': '1M222600258'}
        :rtype: dict
        """
        return RmodOperations._get_rmod_ssh_credentials(connection=connection, rmod_id=rmod_id,
                                                        sw_stream=sw_stream, custom_password=custom_password)

    @log_input_and_output
    def execute_ssh_command(self, rmod_id, command, connection, expected_phrase=None, sw_stream=None, nahka_node=None,
                            timeout=10, switch_to_rfsw_user=True, custom_password=None):
        """
        Executes command on RMOD

        :param rmod_id: RMOD configuration ID of radio module to connect
        :type rmod_id: int
        :param command: command to be executed on RMOD via ssh
        :type command: str
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param expected_phrase: expected phrase which should be contained in command output. If the condition is met
                                function will not wait for the and of timeout
        :type expected_phrase: str
        :param sw_stream: sw stream associated with username and password in init file, default None means sw stream
                          will be detected automatically.
        :type sw_stream: str
        :param nahka_node: ip address of Nahka node to connect on RMOD. Default None means connection to Nahka node
                           is not performed.
        :type nahka_node: str or None
        :param timeout: timeout (in seconds) for send command operation on RMOD, default 10.
        :type timeout: int
        :param switch_to_rfsw_user: True if user wants to switch to 'rfsw' user after connection to RMOD,
                                    False if user wants to stay with 'serviceuser' user. Default True.
        :type switch_to_rfsw_user: bool
        :param custom_password: if provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Default is None, which means password from init file will be used.
        :type custom_password: str or None
        :return: command output
        :rtype: str
        """
        slave_bts = self._check_bts_side_for_rmod_and_set_connection(rmod_id=rmod_id, connection=connection)

        return self._execute_ssh_command(rmod_id=rmod_id, command=command, connection=connection, slave_bts=slave_bts,
                                         expected_phrase=expected_phrase, sw_stream=sw_stream, nahka_node=nahka_node,
                                         timeout=timeout, switch_to_rfsw_user=switch_to_rfsw_user, custom_password=custom_password)

    @log_input_and_output
    def execute_frmon_command(self, rmod_id, command, connection, expected_phrase=None, sw_stream=None, nahka_node=None,
                              timeout=10, switch_to_rfsw_user=True, custom_password=None):
        """
        Executes command on RMOD's FRMon shell. FRMon shell is terminated after command execution using Ctrl+c shortcut.

        :param rmod_id: RMOD configuration ID of radio module to connect
        :type rmod_id: int
        :param command: command to be executed on RMOD's FRMon shell
        :type command: str
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param expected_phrase: expected phrase which should be contained in command output. If the condition is met
                                function will not wait for the and of timeout
        :type expected_phrase: str
        :param sw_stream: sw stream associated with username and password in init file, default None means sw stream
                          will be detected automatically.
        :type sw_stream: str
        :param nahka_node: ip address of Nahka node to connect on RMOD. Default None means connection to Nahka node
                           is not performed.
        :type nahka_node: str or None
        :param timeout: timeout (in seconds) for send command operation on RMOD, default 10.
        :type timeout: int
        :param switch_to_rfsw_user: True if user wants to switch to 'rfsw' user after connection to RMOD,
                                    False if user wants to stay with 'serviceuser' user. Default True.
        :type switch_to_rfsw_user: bool
        :param custom_password: if provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Default is None, which means password from init file will be used.
        :type custom_password: str or None
        :return: command output
        :rtype: str
        """
        slave_bts = self._check_bts_side_for_rmod_and_set_connection(rmod_id=rmod_id, connection=connection)

        self._connect_to_frmon(rmod_id=rmod_id, connection=connection, slave_bts=slave_bts, sw_stream=sw_stream,
                               nahka_node=nahka_node, timeout=timeout, switch_to_rfsw_user=switch_to_rfsw_user,
                               custom_password=custom_password)
        frmon_command = super().send_command_and_return_output(command=command,
                                                               expected_phrase=expected_phrase,
                                                               slave_bts=slave_bts,
                                                               timeout=timeout)
        super().send_command_and_return_output(command='\x03',
                                               slave_bts=slave_bts,
                                               timeout=timeout)

        return frmon_command

    @log_input_and_output
    def enable_rmod_log_handover_to_syslog(self, connection, rmod_id, rmod_protocol, sw_stream=None, timeout=30, switch_to_rfsw_user=True,
                                           custom_password=None, custom_commands=None):
        """
        Enables log handover to syslog on RMOD, which means that logs from RMOD will be collected together with other BTSLog files.
        If rmod_protocol is "eCPRI" then additional step with adding iptables rules to route UDP traffic will be performed.

        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param rmod_id: RMOD configuration ID of particular radio module, e.g.: 1
        :type rmod_id: str or int
        :param rmod_protocol: Protocol type of RMOD. If protocol is different than 'CPRI' or 'eCPRI', custom commands are mandatory to define.
        :type rmod_protocol: str
        :param sw_stream: SW stream associated with username and password in init file, default None means SW stream
                          will be detected automatically.
        :type sw_stream: str
        :param timeout: Allowed time in seconds to complete a command. Defaults to 30
        :type timeout: str or int
        :param switch_to_rfsw_user: True if user wants to switch to 'rfsw' user after connection to RMOD,
                                    False if user wants to stay with 'serviceuser' user. Defaults to True.
        :type switch_to_rfsw_user: bool
        :param custom_password: If provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Defaults to None, which means password from init file will be used.
        :type custom_password: str or None
        :param custom_commands: List of custom commands to enable log handover to syslog on RMOD.
                                If provided, these commands will be used instead of default ones based on RMOD protocol type,
                                e.g.: ['rad -mpw 0x1003f 1', 'rad -mpw 0x10040 1', 'rad -mpw 0x10041 0x2'].
                                Defaults to None, which means default commands will be used based on RMOD protocol type.
        :type custom_commands: list of str or None
        """
        slave_bts = self._check_bts_side_for_rmod_and_set_connection(rmod_id=rmod_id, connection=connection)

        self._rmod_credentials = RmodOperations._get_rmod_ssh_credentials(connection=connection,
                                                                          rmod_id=rmod_id,
                                                                          sw_stream=sw_stream,
                                                                          custom_password=custom_password)

        is_enabled = super().enable_rmod_log_collection_to_syslog(rmod_ip=self._rmod_credentials['ip'],
                                                                  username=self._rmod_credentials['username'],
                                                                  password=self._rmod_credentials['password'],
                                                                  rmod_protocol=rmod_protocol,
                                                                  custom_commands=custom_commands,
                                                                  timeout=int(timeout),
                                                                  slave_bts=slave_bts,
                                                                  switch_to_rfsw=switch_to_rfsw_user)

        if is_enabled:
            log_result(f"Successfully enabled log handover to syslog on RMOD-{rmod_id}")
        return is_enabled

    @log_input_and_output
    def collect_logs_from_rmod(self, rmod_id, local_path, connection, sw_stream=None, timeout=250,
                               switch_to_rfsw_user=True, custom_password=None):
        """
        Collects and downloads logs from RMOD to provided path on VM through invoke shell terminal
        :param rmod_id: RMOD configuration ID of particular radio module, e.g.: 1
        :type rmod_id: str or int
        :param local_path: Path where logs will be saved, must be a path some directory e.g /tmp/logs
        :type local_path: str
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param sw_stream: sw stream associated with username and password in init file, default None means sw stream
                          will be detected automatically.
        :type sw_stream: str
        :param timeout: Allowed time in seconds to complete log collection on RMOD. Default is 250
        :type timeout: int
        :param switch_to_rfsw_user: True if user wants to switch to 'rfsw' user after connection to RMOD,
                                    False if user wants to stay with 'serviceuser' user. Default True.
        :type switch_to_rfsw_user: bool
        :param custom_password: if provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Default is None, which means password from init file will be used.
        :type custom_password: str or None
        :return: True if logs are collected successfully, False otherwise.
        :rtype: bool
        """
        slave_bts = self._check_bts_side_for_rmod_and_set_connection(rmod_id=rmod_id, connection=connection)

        self._rmod_credentials = RmodOperations._get_rmod_ssh_credentials(connection=connection,
                                                                          rmod_id=rmod_id,
                                                                          sw_stream=sw_stream,
                                                                          custom_password=custom_password)

        rmod_serial_number = get_serial_number_for_rmod(rmod_id=rmod_id, connection=connection)
        rmod_log_name = f'RMOD_{rmod_id}_{rmod_serial_number}_logs.zip'
        log_collected = False
        try:
            super().collect_logs_on_rmod_by_log_c_full(rmod_ip=self._rmod_credentials['ip'],
                                                       username=self._rmod_credentials['username'],
                                                       password=self._rmod_credentials['password'],
                                                       filename=rmod_log_name,
                                                       timeout=timeout,
                                                       slave_bts=slave_bts,
                                                       switch_to_rfsw=switch_to_rfsw_user)
            log_to_console(f"Successfully collected logs on RMOD-{rmod_id} with serial number: {rmod_serial_number}")

            self._get_file_from_rmod(rmod_id=rmod_id, filename=rmod_log_name, rmod_path='/ram', local_path=local_path,
                                     connection=connection, slave_bts=slave_bts, sw_stream=None)
            log_to_console(f"RMOD-{rmod_id} log file has been downloaded into {local_path}/{rmod_log_name}")
            log_collected = True
        finally:
            if not log_collected:
                log_to_console(f"RMOD-{rmod_id} log collection failed.")
            return log_collected

    @log_input_and_output
    def get_faults_history_from_rmod(self, rmod_id, connection, convert_to_dict=True, fault_history_log_path='/ram/fault_history_log_temp.txt',
                                     sw_stream=None, timeout=10, switch_to_rfsw_user=True, custom_password=None):
        """
        Gets faults history from RMOD.
        :param rmod_id: RMOD configuration ID of radio module to connect
        :type rmod_id: int
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param convert_to_dict: if True, converts output to dict, default True
        :type convert_to_dict: bool
        :param fault_history_log_path: absolute path to fault history log on rmod,
                                       defaults to '/ram/fault_history_log_temp.txt'
        :type fault_history_log_path: str
        :param sw_stream: sw stream associated with username and password in init file, default None means sw stream
                          will be detected automatically.
        :type sw_stream: str
        :param timeout: timeout (in seconds) for send command operation on RMOD, default 10.
        :type timeout: int
        :param switch_to_rfsw_user: True if user wants to switch to 'rfsw' user after connection to RMOD,
                                    False if user wants to stay with 'serviceuser' user. Default True.
        :type switch_to_rfsw_user: bool
        :param custom_password: if provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Default is None, which means password from init file will be used.
        :type custom_password: str or None
        :return: If `convert_to_dict=False` returns raw terminal output. If `convert_to_dict=True` returns dict with parsed alarms e.g.:
           {'Fault report': datetime,
            'Active faults': [],
            'InActive faults': [{'timestamp': datetime, 'id': 'EFaultId_Lock (11)', 'source': 'module', 'severity': 'critical', 'numofFaults': '2'}],
            'Fault events': [{'timestamp': datetime, 'id': 'EFaultId_Blocked (12)', 'source': 'module', 'severity': 'critical', 'state': 'active'}]}
        :rtype: str or dict
        """
        slave_bts = self._check_bts_side_for_rmod_and_set_connection(rmod_id=rmod_id, connection=connection)
        terminal_output = self._execute_ssh_command(rmod_id=rmod_id, command=f'cat {fault_history_log_path}', connection=connection,
                                                    slave_bts=slave_bts, sw_stream=sw_stream, timeout=timeout,
                                                    switch_to_rfsw_user=switch_to_rfsw_user, custom_password=custom_password)

        return self._parse_faults_history(terminal_output) if convert_to_dict else terminal_output

    @log_input_and_output
    def get_date_of_last_rmod_startup(self, rmod_id, connection, sw_stream=None, timeout=10, switch_to_rfsw_user=True, custom_password=None):
        """
        Gets datetime of last RMOD startup based on current date and time.
        :param rmod_id: RMOD configuration ID of radio module to connect, e.g.: 1
        :type rmod_id: int
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param sw_stream: sw stream associated with username and password in init file, default None means sw stream
                          will be detected automatically.
        :type sw_stream: str
        :param timeout: timeout (in seconds) for send command operation on RMOD, default 10.
        :type timeout: int
        :param switch_to_rfsw_user: True if user wants to switch to 'rfsw' user after connection to RMOD,
                                    False if user wants to stay with 'serviceuser' user. Default True.
        :type switch_to_rfsw_user: bool
        :param custom_password: if provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Default is None, which means password from init file will be used.
        :type custom_password: str or None
        :return: datetime of last rmod startup, e.g.: 2024-10-02 04:55:50.000
        :rtype: datetime

        :raises CommandExecutionError exception when unexpected uptime format in RMOD's output.
        """
        slave_bts = self._check_bts_side_for_rmod_and_set_connection(rmod_id=rmod_id, connection=connection)

        uptime_sec = self._get_proc_uptime_in_seconds(rmod_id=rmod_id, connection=connection, slave_bts=slave_bts,
                                                      sw_stream=sw_stream, timeout=timeout, switch_to_rfsw_user=switch_to_rfsw_user,
                                                      custom_password=custom_password)

        current_time = datetime.now()

        rmod_startup = current_time - timedelta(seconds=uptime_sec)

        return rmod_startup.replace(microsecond=0)

    @log_input_and_output
    def check_if_fault_exists_in_faults_history_log_on_rmod(self, rmod_id, fault_type, expected_fault, connection,
                                                            fault_history_log_path='/ram/fault_history_log_temp.txt',
                                                            sw_stream=None, timeout=10):
        """
        Check if particular fault exists in fault history log file located on RMOD.
        :param rmod_id: RMOD configuration ID of radio module to connect
        :type rmod_id: int
        :param fault_type: type of expected fault, where expected_fault will be looked for, one of following:
                           'Active faults', 'InActive faults' or 'Fault events'
        :type fault_type: str
        :param expected_fault: Fault to search for in RMOD fault history. It can be provided as:
                               *str, which will be considered as the [ID] column (in RMOD fault_history_log_temp.txt file), e.g. EFaultId_Lock (11)
                               *dict with fault with all details, e.g.: {'id': 'EFaultId_Lock (11)', 'source': 'module', 'severity': 'critical'}
        :type expected_fault: str or dict
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param fault_history_log_path: absolute path to fault history log on rmod,
                                       defaults to '/ram/fault_history_log_temp.txt'
        :type fault_history_log_path: str
        :param sw_stream: sw stream associated with username and password in init file, default None means sw stream
                          will be detected automatically.
        :type sw_stream: str
        :param timeout: timeout (in seconds) for getting fault history log from RMOD, default 10.
        :type timeout: int
        :return: True if particular fault name exists in given fault type section, False otherwise
        :rtype: bool
        """
        fault_history_dict = self.get_faults_history_from_rmod(rmod_id=rmod_id, connection=connection, fault_history_log_path=fault_history_log_path,
                                                               convert_to_dict=True, sw_stream=sw_stream, timeout=timeout)

        if isinstance(expected_fault, str):
            expected_fault = {'id': expected_fault}

        for fault in fault_history_dict[fault_type]:
            if all(fault[key] == value for key, value in expected_fault.items()):
                return True
        return False

    @log_input_and_output
    def get_file_from_rmod(self, rmod_id, filename, rmod_path, local_path, connection, sw_stream=None):
        """
        Gets file from RMOD and save file under provided local path.

        :param rmod_id: RMOD configuration ID of radio module to connect
        :type rmod_id: int
        :param filename: name of file to get from RMOD, e.g.: config.txt
        :type filename: str
        :param rmod_path: filepath of file to get from RMOD, e.g.: /ram
        :type rmod_path: str
        :param local_path: Path where logs will be saved, must be a path to some directory e.g. /tmp/logs
        :type local_path: str
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param sw_stream: sw stream associated with username and password in init file, default None means sw stream
                          will be detected automatically.
        :type sw_stream: str
        :return: absolute path to downloaded file
        :rtype: str
        """
        slave_bts = self._check_bts_side_for_rmod_and_set_connection(rmod_id=rmod_id, connection=connection)

        log_to_console(f"Downloading '{rmod_path}/{filename}' file from RMOD-{rmod_id}...")
        return self._get_file_from_rmod(rmod_id=rmod_id, filename=filename, rmod_path=rmod_path, local_path=local_path,
                                        connection=connection, slave_bts=slave_bts, sw_stream=sw_stream)

    @log_input_and_output
    def get_file_from_rmod_with_rmod_index(self, rmod_index, download_path, connection, rmod_path, rmod_file_name, custom_password=None):
        """
        Gets file from rmod. Specified filename will be downloaded from rmod with given index. Supports full rack
        config. Downloaded filename has format: RMOD-<rmod_index>_<rmod_file_name>.

        :param rmod_index: rmod index from which the file will be downloaded
        :type rmod_index: int
        :param download_path: path to directory where the files will be downloaded
        :type download_path: str
        :param connection: AdminConnection object or, if used, string name alias
        :type connection: AdminConnection or str
        :param rmod_path: path to the file on rmod
        :type rmod_path: str
        :param rmod_file_name: unique filename
        :type rmod_file_name: str
        :param custom_password: if provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Default is None, which means password from init file will be used.
        :type custom_password: str or None
        :return: path to downloaded file
        :rtype: str
        """
        final_file_path = '{}/RMOD-{}_{}'.format(download_path, rmod_index, rmod_file_name)
        log_to_console('Downloading {}/{} file from RMOD-{}...'.format(rmod_path, rmod_file_name, rmod_index))

        slave_bts = self._check_bts_side_for_rmod_and_set_connection(rmod_id=rmod_index, connection=connection)
        self._get_file_from_rmod(rmod_id=rmod_index, filename=rmod_file_name, rmod_path=rmod_path,
                                 local_path=download_path, connection=connection, slave_bts=slave_bts,
                                 custom_password=custom_password)
        move_file_to_target_directory('{}/{}'.format(download_path, rmod_file_name), final_file_path)
        return final_file_path

    @log_input_and_output
    def send_file_to_rmod(self, rmod_id, filename, rmod_path, local_path, connection, sw_stream=None,
                          switch_to_rfsw_user=True, custom_password=None):
        """
        Sends file to RMOD from provided local path.

        :param rmod_id: RMOD configuration ID of radio module to connect
        :type rmod_id: int
        :param filename: name of file to send to RMOD, e.g.: config.txt
        :type filename: str
        :param rmod_path: Path where file will by copied on RMOD, must be a path to some directory e.g. /ram
        :type rmod_path: str
        :param local_path: filepath of file to send to RMOD, e.g.: /tmp/logs
        :type local_path: str
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param sw_stream: sw stream associated with username and password in init file, default None means sw stream
                          will be detected automatically.
        :type sw_stream: str
        :param switch_to_rfsw_user: True if user wants to switch to 'rfsw' user after connection to RMOD,
                                    False if user wants to stay with 'serviceuser' user. Default True.
        :type switch_to_rfsw_user: bool
        :param custom_password: if provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Default is None, which means password from init file will be used.
        :type custom_password: str or None
        :return: absolute path to downloaded file
        :rtype: str
        """
        slave_bts = self._check_bts_side_for_rmod_and_set_connection(rmod_id=rmod_id, connection=connection)

        self._rmod_credentials = RmodOperations._get_rmod_ssh_credentials(connection=connection,
                                                                          rmod_id=rmod_id,
                                                                          sw_stream=sw_stream,
                                                                          custom_password=custom_password)
        self._get_current_output_and_reconnect_channel_if_needed(slave_bts=slave_bts)
        super().upload_file_from_vm_to_smod(filename=filename, smod_path="/ram", local_path=local_path,
                                            slave_bts=slave_bts)

        log_to_console(f"Sending '{local_path}/{filename}' file to '{rmod_path}' on RMOD-{rmod_id}...")
        super().send_file_from_smod_to_rmod(filename=filename, smod_path="/ram", rmod_path=rmod_path,
                                            rmod_ip=self._rmod_credentials['ip'],
                                            username=self._rmod_credentials['username'],
                                            password=self._rmod_credentials['password'],
                                            slave_bts=slave_bts,
                                            switch_to_rfsw=switch_to_rfsw_user)
        log_to_console("File has been sent successfully.")
        return f"{rmod_path}/{filename}"

    @log_input_and_output
    def kill_rmod_process_by_name(self, rmod_id, process_name, connection, signal_number=9, root_process=False,
                                  sw_stream=None, timeout=10, switch_to_rfsw_user=True, custom_password=None):
        """
        Kills process on rmod by given process name and returns PID of killed process.

        :param rmod_id: RMOD configuration ID of radio module to connect
        :type rmod_id: int
        :param process_name: full name or pattern to rmod's process to kill, e.g.: '/lib/systemd/systemd --user'
        :type process_name: str
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param signal_number: signal number to be used for killing process, defaults to 9 (SIGKILL).
        :type signal_number: int
        :param root_process: True if given process name is running as root, False otherwise. Defaults to False
        :type root_process: bool
        :param sw_stream: sw stream associated with username and password in init file, default None means sw stream
                          will be detected automatically.
        :type sw_stream: str
        :param timeout: timeout (in seconds) for send kill process command on RMOD, defaults to 10.
        :type timeout: int
        :param switch_to_rfsw_user: True if user wants to switch to 'rfsw' user after connection to RMOD,
                                    False if user wants to stay with 'serviceuser' user. Default True.
        :type switch_to_rfsw_user: bool
        :param custom_password: if provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Default is None, which means password from init file will be used.
        :type custom_password: str or None
        :return: PID of killed process
        :rtype: int

        :raises PIDNotFound exception when no process ID was found with the given process name
        :raises CommandExecutionError exception when 'kill -11' command was not executed successfully.
        """
        slave_bts = self._check_bts_side_for_rmod_and_set_connection(rmod_id=rmod_id, connection=connection)

        self._connect_rmod_ssh(rmod_id=rmod_id,
                               connection=connection,
                               slave_bts=slave_bts,
                               sw_stream=sw_stream,
                               switch_to_rfsw_user=switch_to_rfsw_user,
                               custom_password=custom_password)

        pid_list = self._get_list_of_process_ids(rmod_id=rmod_id,
                                                 processes_print_command=f"ps | grep {process_name} | grep -v grep",
                                                 root_process=root_process, connection=connection, slave_bts=slave_bts,
                                                 sw_stream=sw_stream, timeout=timeout, switch_to_rfsw_user=switch_to_rfsw_user,
                                                 custom_password=custom_password)

        if not pid_list:
            pid_list = self._get_list_of_process_ids(rmod_id=rmod_id,
                                                     processes_print_command=f"ps -aux | grep {process_name} | grep -v grep",
                                                     root_process=root_process, connection=connection,
                                                     slave_bts=slave_bts, sw_stream=sw_stream, timeout=timeout,
                                                     switch_to_rfsw_user=switch_to_rfsw_user, custom_password=custom_password)

        if not pid_list:
            raise PIDNotFound(f"PID not found for given process name:'{process_name}'")

        kill_command = f"{'sudo ' if root_process or self._rmod_credentials['username'] == 'serviceuser' else ''}kill -{signal_number} {pid_list[0]}"

        kill_result = super().send_command_and_return_output(command=kill_command, slave_bts=slave_bts,
                                                             timeout=timeout)

        if "No such process" in kill_result or "unknown" in kill_result:
            raise CommandExecutionError(f"Kill process failure: '{kill_result}'")

        if "Operation not permitted" in kill_result:
            raise CommandExecutionError(f"No permission to kill process: '{kill_result}'")

        return int(pid_list[0])

    @log_input_and_output
    def get_sw_version_details_from_rmod(self, rmod_id, connection, timeout=10, switch_to_rfsw_user=True, custom_password=None):
        """
        Gets software version details from RMOD via SWmanShellCommand command.

        :param rmod_id: RMOD configuration ID of radio module to connect
        :type rmod_id: int
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param timeout: timeout (in seconds) for send command operation on RMOD, default 10.
        :type timeout: int
        :param switch_to_rfsw_user: True if user wants to switch to 'rfsw' user after connection to RMOD,
                                    False if user wants to stay with 'serviceuser' user. Default True.
        :type switch_to_rfsw_user: bool
        :param custom_password: if provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Default is None, which means password from init file will be used.
        :type custom_password: str or None
        :return: software version details,  e.g. :
        {'File numbers': '2',
         'SwInventoryResp': '',
         'Current runningBuildName': 'RF.ERM6.trunk.20240822.013',
         'Current runningBuildVersion': 'RF.ERM6.trunk.20240822.013,2024-08-22T13',
         'activeBuildName': 'RF.ERM6.trunk.20240822.013',
         'activeBuildVersion': 'RF.ERM6.trunk.20240822.013,2024-08-22T13',
         'File [0] name': 'rfsw-package-erm6_0xFA0E83F1.tar',
         'File [0] version': '0xFA0E83F1',
         'File [0] usage': "1 - it's active",
         'File [0] integrity': 'Valid',
         'File [1] name': 'rfsw-package-erm6_0xAD073892.tar',
         'File [1] version': '0xAD073892',
         'File [1] usage': "0 - it's passive",
         'File [1] integrity': 'Valid'}
        :rtype: dict
        """
        slave_bts = self._check_bts_side_for_rmod_and_set_connection(rmod_id=rmod_id, connection=connection)

        terminal_output = self._execute_ssh_command(rmod_id=rmod_id, command='SWmanShellCommand -i',
                                                    connection=connection, slave_bts=slave_bts, timeout=timeout,
                                                    switch_to_rfsw_user=switch_to_rfsw_user, custom_password=custom_password)

        terminal_output = terminal_output.replace("\r", "")
        terminal_output = re.split(r"(File)", terminal_output)[1:]
        for ind, line in enumerate(terminal_output):
            if 'File' in line:
                terminal_output[ind] = terminal_output[ind] + terminal_output[ind + 1]
                terminal_output.pop(ind + 1)

        sw_version_details = {}
        file_number = 0
        for part in terminal_output:
            part_lines = part.split('\n')
            prefix = ''
            for line in part_lines:
                if '[{}]'.format(file_number) in line:
                    prefix = 'File [{}] '.format(file_number)
                    file_number += 1
                    continue
                if ':' in line:
                    sw_version_details[prefix + line.split(':')[0].strip()] = line.split(':')[1].strip()
        return sw_version_details

    @staticmethod
    @log_input_and_output
    def _get_rmod_ssh_credentials(connection, rmod_id, sw_stream=None, custom_password=None):
        """
        Gets RMOD ssh credentials based on provided RMOD ID. Login and password are getting from init file,
        ip address and serial number are getting using admin.
        :param connection: AdminConnection object or if used, string name alias
        :type connection: AdminConnection or str
        :param rmod_id: RMOD configuration ID of particular radio module, e.g.: 1
        :type rmod_id: str or int
        :param sw_stream: Software stream of uploaded BTS package e.g.: '23R3', default equal as None means sw_stream
                          will be detected automatically
        :param custom_password: if provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Default is None, which means password from init file will be used.
        :type custom_password: str or None
        :type sw_stream: str
        :return: dict of RMOD credentials with following keys: 'ip', 'username', 'password' and 'sn',
                 e.g. : {'ip': '172.22.8.2', 'username': 'rfsw',
                         'password': 'KRG3dFggxxHw+s0z64U0AR22VyjfnXdHrAVdSv5jpc4=',
                         'sn': '1M222600258'}
        :rtype: dict
        """
        testline = TestLine()

        sw_stream = get_sw_stream() if sw_stream is None else sw_stream
        searched_rmod_sn = get_serial_number_for_rmod(connection=connection, rmod_id=rmod_id)
        rmods_serial_number_ip = get_rmods_ip(connection)
        username, password = testline.get_rmod_credentials_by_sn(rmod_sn=searched_rmod_sn, sw_stream=sw_stream)
        if custom_password is not None:
            password = custom_password

        rmod_ssh_credentials = {'ip': rmods_serial_number_ip[searched_rmod_sn],
                                'username': username,
                                'password': password,
                                'sn': searched_rmod_sn}

        return rmod_ssh_credentials

    @reconnect_session_and_repeat_operation_when_oserror
    @log_input_and_output
    def _connect_rmod_ssh(self, rmod_id, connection, slave_bts, sw_stream=None, nahka_node=None, switch_to_rfsw_user=True, custom_password=None):
        """
        Connects to RMOD via ssh invoke shell. If connection is currently established to RMOD, no additional action
        is needed.

        :param rmod_id: RMOD configuration ID of radio module to connect
        :type rmod_id: int
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param slave_bts: True if connection should be performed to slave bts,
                          False in case of master bts connection or configurations other than fullrack.
        :type slave_bts: bool
        :param sw_stream: sw stream associated with username and password in init file, e.g.: 'SBTS24R1'
        ...               Default None means sw stream
                          will be detected automatically.
        :type sw_stream: str
        :param nahka_node: ip address of Nahka node to connect on RMOD. Default None means connection to Nahka node
                           is not performed.
        :type nahka_node: str or None
        :param switch_to_rfsw_user: True if user wants to switch to 'rfsw' user after connection to RMOD,
                                    False if user wants to stay with 'serviceuser' user. Default True.
        :type switch_to_rfsw_user: bool
        :param custom_password: if provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Default is None, which means password from init file will be used.
        :type custom_password: str or None
        :return: True when connection to rmod succeeded.
        :rtype: bool
        :raises BTSConnectionError exception when BTS connection has unknown status.
        """

        super().send_command_and_return_output(command="\x03", timeout=5, slave_bts=slave_bts)
        current_line = self._get_current_output_and_reconnect_channel_if_needed(slave_bts=slave_bts)
        for _ in range(3):
            if "@FHNET" in current_line or bool(re.search(r"root@.*-[04]a", current_line)):
                self._rmod_credentials = RmodOperations._get_rmod_ssh_credentials(connection=connection,
                                                                                  rmod_id=rmod_id,
                                                                                  sw_stream=sw_stream,
                                                                                  custom_password=custom_password)
                super().connect_to_rmod(ip=self._rmod_credentials['ip'],
                                        username=self._rmod_credentials['username'],
                                        password=self._rmod_credentials['password'],
                                        slave_bts=slave_bts,
                                        switch_to_rfsw=switch_to_rfsw_user)
                if nahka_node is not None:
                    self._connect_to_nahka_node(nahka_ip=nahka_node, slave_bts=slave_bts)
                return True
            current_line = super().send_command_and_return_output(command="exit", timeout=5, slave_bts=slave_bts)

        raise BtsConnectionFailed("RMOD connection failed: Unknown BTS connection status")

    @log_input_and_output
    def _get_current_output_and_reconnect_channel_if_needed(self, slave_bts):
        """
        Gets output of command '\r\n' sent on RMOD via active ssh invoke session channel.
        Ssh invoke session channel is reconnected in case of empty first send command output.

        :return: output of command '\r\n' sent on RMOD via active ssh invoke session channel
        :rtype: str
        """
        current_line = super().send_command_and_return_output(command='\r\n', timeout=5, slave_bts=slave_bts)
        if current_line == "" or "The system will reboot now!" in current_line:
            super().reconnect_channel_session()
            current_line = super().send_command_and_return_output(command='\r\n', timeout=5, slave_bts=slave_bts)
        return current_line

    @log_input_and_output
    def _connect_to_frmon(self, rmod_id, connection, slave_bts, sw_stream=None,
                          nahka_node=None, timeout=10, switch_to_rfsw_user=True, custom_password=None):
        """
        Connects to FRMON shell

        :param rmod_id: RMOD configuration ID of radio module to connect
        :type rmod_id: int
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param slave_bts: Used for fullrack configuration only. True if connection should be performed to slave bts,
                          False in case of master bts connection or configurations other than fullrack.
                          Defaults to False.
        :type slave_bts: bool
        :param sw_stream: sw stream associated with username and password in init file, default None means sw stream
                          will be detected automatically.
        :type sw_stream: str
        :param nahka_node: ip address of Nahka node to connect on RMOD. Default None means connection to Nahka node
                           is not performed.
        :type nahka_node: str or None
        :param timeout: timeout (in seconds) for send command operation on RMOD, default 10.
        :type timeout: int
        :param switch_to_rfsw_user: True if user wants to switch to 'rfsw' user after connection to RMOD,
                                    False if user wants to stay with 'serviceuser' user. Default True.
        :type switch_to_rfsw_user: bool
        :param custom_password: if provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Default is None, which means password from init file will be used.
        :type custom_password: str or None

        :raises FrmonConnectionFailed: if FRMon connection failed.
        """
        self._connect_rmod_ssh(rmod_id=rmod_id,
                               connection=connection,
                               slave_bts=slave_bts,
                               sw_stream=sw_stream,
                               nahka_node=nahka_node,
                               switch_to_rfsw_user=switch_to_rfsw_user,
                               custom_password=custom_password)
        frmon_conn = super().send_command_and_return_output(command="frmonShellClient",
                                                            expected_phrase="frmonShellClient starting "
                                                                            "on ip:localhost port:2000",
                                                            slave_bts=slave_bts,
                                                            timeout=timeout)
        if "frmonShellClient starting on ip:localhost port:2000" not in frmon_conn:
            raise FrmonConnectionFailed("FRMON connection failed, please check if FRMon shell is supported on RMOD")
        log_operation("FRMON connection succeeded")

    @log_input_and_output
    def _connect_to_nahka_node(self, nahka_ip, slave_bts, timeout=10):
        """
        Connects to Nahka node

        :param nahka_ip: ip address of Nahka node, e.g. "192.168.101.5"
        :type nahka_ip: str
        :param slave_bts: True if connection should be performed to slave bts,
                          False in case of master bts connection or configurations other than fullrack.
        :type slave_bts: bool
        :param timeout: timeout (in seconds) for send command operation on RMOD, default 10.
        :type timeout: int

        :raises FrmonConnectionFailed: if FRMon connection failed.
        """
        nahka_conn = super().send_command_and_return_output(command=f"ssh {nahka_ip}",
                                                            slave_bts=slave_bts,
                                                            timeout=timeout)
        if "Are you sure you want to continue connecting (yes/no)?" in nahka_conn:
            nahka_conn = super().send_command_and_return_output(command="yes",
                                                                slave_bts=slave_bts,
                                                                timeout=timeout)
        if "root@nahka-Node" not in nahka_conn:
            raise NahkaConnectionFailed(f"Nahka connection failed, please check if RMOD has nahka layer "
                                        f"with ip address {nahka_ip}")

        log_operation("FRMON connection succeeded")

    @log_input_and_output
    def _execute_ssh_command(self, rmod_id, command, connection, slave_bts, expected_phrase=None, sw_stream=None,
                             nahka_node=None, timeout=10, switch_to_rfsw_user=True, custom_password=None):
        """
        Executes command on RMOD

        :param rmod_id: RMOD configuration ID of radio module to connect
        :type rmod_id: int
        :param command: command to be executed on RMOD via ssh
        :type command: str
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param slave_bts: True if connection should be performed to slave bts,
                          False in case of master bts connection or configurations other than fullrack.
        :type slave_bts: bool
        :param expected_phrase: expected phrase which should be contained in command output. If the condition is met
                                function will not wait for the and of timeout
        :type expected_phrase: str
        :param sw_stream: sw stream associated with username and password in init file, default None means sw stream
                          will be detected automatically.
        :type sw_stream: str
        :param nahka_node: ip address of Nahka node to connect on RMOD. Default None means connection to Nahka node
                           is not performed.
        :type nahka_node: str or None
        :param timeout: timeout (in seconds) for send command operation on RMOD, default 10.
        :type timeout: int
        :param switch_to_rfsw_user: True if user wants to switch to 'rfsw' user after connection to RMOD,
                                    False if user wants to stay with 'serviceuser' user. Default True.
        :type switch_to_rfsw_user: bool
        :param custom_password: if provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Default is None, which means password from init file will be used.
        :type custom_password: str or None
        :return: command output
        :rtype: str
        """
        self._connect_rmod_ssh(rmod_id=rmod_id,
                               connection=connection,
                               slave_bts=slave_bts,
                               sw_stream=sw_stream,
                               nahka_node=nahka_node,
                               switch_to_rfsw_user=switch_to_rfsw_user,
                               custom_password=custom_password)
        return super().send_command_and_return_output(command=command,
                                                      expected_phrase=expected_phrase,
                                                      slave_bts=slave_bts,
                                                      timeout=timeout)

    @staticmethod
    def _get_rus_ips_and_serial_numbers_from_smod():
        smod_credentials = get_ssh_connection_credentials()
        smod = Smod()

        try:
            smod.connect_to(address=smod_credentials['host'], username=smod_credentials['username'],
                            password=smod_credentials['password'], alias="rmod_operations")
            return smod.get_rus_ips_and_serial_numbers()
        finally:
            smod.close_connection()

    @log_input_and_output
    def _check_bts_side_for_rmod_and_set_connection(self, rmod_id, connection):

        smod_active_role = get_smod_active_role_for_connected_rmod(rmod_id=rmod_id, connection=connection)
        is_rmod_connected_to_slave_bts = True if smod_active_role == "Secondary" else False

        super().check_session_to_particular_bts_side_and_reconnect_session_if_needed(
            slave_bts=is_rmod_connected_to_slave_bts)

        return is_rmod_connected_to_slave_bts

    @log_input_and_output
    def _get_list_of_process_ids(self, rmod_id, processes_print_command, root_process, connection, slave_bts,
                                 sw_stream=None, timeout=10, switch_to_rfsw_user=True, custom_password=None):
        self._connect_rmod_ssh(rmod_id=rmod_id,
                               connection=connection,
                               slave_bts=slave_bts,
                               sw_stream=sw_stream,
                               switch_to_rfsw_user=switch_to_rfsw_user,
                               custom_password=custom_password)

        ps_return = super().send_command_and_return_output(command=processes_print_command,
                                                           slave_bts=slave_bts,
                                                           timeout=timeout)

        if root_process:
            process_user = "root"
        elif self._rmod_credentials['username'] == "serviceuser":
            process_user = "rfsw"
        else:
            process_user = self._rmod_credentials['username']

        pid_list = []
        for line in ps_return.split("\r\n"):
            if re.search(fr"[0-9]+\s{process_user}", line):
                pid = int(line.split(f"{process_user}")[0])
                pid_list.append(pid)
            elif re.search(fr"{process_user}\s+[0-9]+\s", line):
                pid = int(line.split()[1])
                pid_list.append(pid)

        return pid_list

    @log_input_and_output
    def _get_file_from_rmod(self, rmod_id, filename, rmod_path, local_path, connection, slave_bts,
                            sw_stream=None, switch_to_rfsw_user=True, custom_password=None):
        """
        Gets file from RMOD and save file under provided local path.

        :param rmod_id: RMOD configuration ID of radio module to connect
        :param filename: name of file to get from RMOD, e.g.: config.txt
        :type filename: str
        :param rmod_path: filepath of file to get from RMOD, e.g.: /ram
        :type rmod_path: str
        :param local_path: Path where logs will be saved, must be a path to some directory e.g. /tmp/logs
        :type local_path: str
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param slave_bts: Used for fullrack configuration only. True if connection should be performed to slave bts,
                          False in case of master bts connection or configurations other than fullrack.
        :type slave_bts: bool
        :param sw_stream: sw stream associated with username and password in init file, default None means sw stream
                          will be detected automatically.
        :type sw_stream: str
        :param switch_to_rfsw_user: True if user wants to switch to 'rfsw' user after connection to RMOD,
                                    False if user wants to stay with 'serviceuser' user.
        :type switch_to_rfsw_user: bool
        :param custom_password: if provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Default is None, which means password from init file will be used.
        :type custom_password: str or None
        :return: absolute path to downloaded file
        :rtype: str
        """

        self._rmod_credentials = RmodOperations._get_rmod_ssh_credentials(connection=connection,
                                                                          rmod_id=rmod_id,
                                                                          sw_stream=sw_stream,
                                                                          custom_password=custom_password)
        self._get_current_output_and_reconnect_channel_if_needed(slave_bts=slave_bts)
        super().get_file_from_rmod_to_smod(filename=filename, smod_path="/ram", rmod_path=rmod_path,
                                           rmod_ip=self._rmod_credentials['ip'],
                                           username=self._rmod_credentials['username'],
                                           password=self._rmod_credentials['password'],
                                           slave_bts=slave_bts,
                                           switch_to_rfsw=switch_to_rfsw_user)

        super().download_file_from_smod_to_vm(filename=filename, smod_path="/ram", local_path=local_path,
                                              slave_bts=slave_bts)
        log_to_console("File has been downloaded successfully.")

        return f"{local_path}/{filename}"

    def _parse_faults_history(self, faults_history):
        """
        Parse 'cat /ram/fault_history_log_temp.txt' terminal output.
        :param faults_history: Fault history from terminal output.
        :type faults_history: str
        :return: Parsed fault history as dictionary. E.g.:
            {'Fault report': datetime,
             'Active faults': [{'timestamp': datetime, 'id': EFaultId_Blocked (1), 'source': 'module', 'severity': 'critical', 'numofFaults': 1}],
             'InActive faults': [{'timestamp': datetime, 'id': EFaultId_Lock (112), 'source': 'module', 'severity': 'warning', 'numofFaults': '2'}}],
             'Fault events': [{'timestamp': datetime, 'id': EFaultId_BMU (10), 'source': 'module', 'severity': 'warning', 'state': 'active'}]}
        :rtype: dict
        """
        fault_history = {}

        fault_history['Fault report'] = convert_timestamp_to_datetime(re.search(r"Fault report:.*?<(.*?)>.*?Active", faults_history,
                                                                                re.DOTALL).group(1), time_format='%Y-%m-%dT%H:%M:%S.%fZ')
        patterns = {"Active faults": r"Active faults:(.*)InActive",
                    "InActive faults": r"InActive faults:(.*)Fault events",
                    "Fault events": r"Fault events:(.*)"}

        for faults_category, pattern in patterns.items():
            alarm_content_lines = re.sub(r'[\r\t]+', '', (re.search(pattern, faults_history, re.DOTALL).group(1)).strip()).splitlines()
            fault_history[faults_category] = [self._parse_fault_history_alarm(line.strip(), faults_category) for line in alarm_content_lines
                                              if line.strip().startswith('<')]

        return fault_history

    def _parse_fault_history_alarm(self, alarm, fault_category):
        """
        Parse line from fault history containing alarm description.

        :param alarm: Line containing alarm description e.g. '<2025-03-20T13:12:48.274000Z> EFaultId_Blocked (1162)  module    critical    2'
        :type alarm: str
        :return: Parsed alarm as dictionary. E.g.:
            {'timestamp': datetime, 'id': EFaultId_Blocked (1), 'source': 'module', 'severity': 'critical', 'numofFaults': 1}
        :rtype: dict
        """
        timestamp, _name, _id, source, severity, numof_or_state = re.findall(r'\S+', alarm)
        alarm_dict = {
            'timestamp': convert_timestamp_to_datetime(timestamp.strip('<>'), '%Y-%m-%dT%H:%M:%S.%fZ'),
            'id': f"{_name} {_id}",
            'source': source,
            'severity': severity,
            'state' if fault_category == 'Fault events' else 'numofFaults': numof_or_state
        }

        return alarm_dict

    @log_input_and_output
    def _get_proc_uptime_in_seconds(self, rmod_id, connection, slave_bts, sw_stream, timeout=10,
                                    switch_to_rfsw_user=True, custom_password=None):
        """
        Gets RMOD's processor uptime based on "cat /proc/uptime | awk '{print $1}'" command.
        :param rmod_id: RMOD configuration ID of radio module to connect, e.g.: 1
        :type rmod_id: int
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param slave_bts: True if connection should be performed to slave bts,
                          False in case of master bts connection or configurations other than fullrack.
        :type slave_bts: bool
        :param sw_stream: sw stream associated with username and password in init file, if is None, sw stream
                          will be detected automatically.
        :type sw_stream: str
        :param timeout: timeout (in seconds) for send command operation on RMOD, default 10.
        :type timeout: int
        :param switch_to_rfsw_user: True if user wants to switch to 'rfsw' user after connection to RMOD,
                                    False if user wants to stay with 'serviceuser' user. Default True.
        :type switch_to_rfsw_user: bool
        :param custom_password: if provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Default is None, which means password from init file will be used.
        :type custom_password: str or None
        :return: rmod's processor uptime in seconds, e.g.: 2161.19
        :rtype: float

        :raises CommandExecutionError exception when unexpected uptime format in RMOD's output.
        """
        terminal_output = self._execute_ssh_command(rmod_id=rmod_id, command="cat /proc/uptime | awk '{print $1}'",
                                                    connection=connection, slave_bts=slave_bts, sw_stream=sw_stream,
                                                    timeout=timeout, switch_to_rfsw_user=switch_to_rfsw_user,
                                                    custom_password=custom_password)

        for line in terminal_output.split("\r\n"):
            uptime = re.search(r"[0-9]*\.[0-9]*", line)
            if uptime:
                return float(uptime.group())

        raise CommandExecutionError(f"Uptime not found in terminal output: {terminal_output}")

    def get_bmu_version(self, rmod_id, connection, timeout=10, switch_to_rfsw_user=True, rsc_ops=None, custom_password=None):
        """
        Gets from RMOD '/var/log/uboot/uboot_pm0' file or from master serial logs if LMI connected BMU version.

        :param rmod_id: RMOD configuration ID of radio module to connect
        :type rmod_id: str or int
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param timeout: timeout (in seconds) for send command operation on RMOD, default 10.
        :type timeout: int
        :param switch_to_rfsw_user: True if user wants to switch to 'rfsw' user after connection to RMOD,
                                    False if user wants to stay with 'serviceuser' user. Default True.
        :type switch_to_rfsw_user: bool
        :param rsc_ops: RmodSerialConsoleOperations object. If None, BMU version will be retrieved from RMOD only.
        :type rsc_ops: RmodSerialConsoleOperations
        :param custom_password: if provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Default is None, which means password from init file will be used.
        :type custom_password: str or None
        :raises BMUversionNotFound exception when BMU version was not found.
        :return: BMU version e.g. '0x4_0x0_0x1'
        """
        rmod_sn = get_serial_number_for_rmod(connection=connection, rmod_id=rmod_id)
        if rsc_ops is not None:
            rdc_alias = rsc_ops.get_init_serial_console_alias_for_serial_number(rmod_sn)
        if custom_password is not None:
            rsc_ops.update_credentials_for_rmod_serial_console_connection(init_radio_id=rmod_id, password=custom_password)
        if rdc_alias is not None:
            try:
                return self._get_bmu_version_from_serial_logs(rdc_alias, rsc_ops)
            except BMUversionNotFound:
                pass
        return self._get_bmu_version_from_rmod(rmod_id=rmod_id, connection=connection,
                                               timeout=timeout, switch_to_rfsw_user=switch_to_rfsw_user,
                                               custom_password=custom_password)

    @log_input_and_output
    def _get_bmu_version_from_rmod(self, rmod_id, connection, timeout=10, switch_to_rfsw_user=True, custom_password=None):
        """
        Gets BMU version from RMOD based on 'cat /var/log/uboot_pm0 | grep "Bmu image is up to date"' command.

        :param rmod_id: RMOD configuration ID of radio module to connect
        :type rmod_id: str or int
        :param connection: AdminConnection object or, if used, string name alias.
        :type connection: AdminConnection or str
        :param timeout: timeout (in seconds) for send command operation on RMOD, default 10.
        :type timeout: int
        :param switch_to_rfsw_user: True if user wants to switch to 'rfsw' user after connection to RMOD,
                                    False if user wants to stay with 'serviceuser' user. Default True.
        :type switch_to_rfsw_user: bool
        :param custom_password: if provided, this password will be used for RMOD ssh connection instead of
                                password from init file. Default is None, which means password from init file will be used.
        :type custom_password: str or None
        :return: BMU version e.g. '0x4_0x0_0x1'
        :rtype: str
        :raises BMUversionNotFound exception when BMU version was not found.
        """
        slave_bts = self._check_bts_side_for_rmod_and_set_connection(rmod_id=rmod_id, connection=connection)
        command = 'cat /var/log/uboot_pm0 | grep "Bmu image is up to date"'
        output = self._execute_ssh_command(rmod_id=rmod_id, command=command, connection=connection, slave_bts=slave_bts, timeout=timeout,
                                           switch_to_rfsw_user=switch_to_rfsw_user, custom_password=custom_password)

        match = re.search(r'ver = (.*?)[)]', output)
        if match:
            return match.group(1)

        raise BMUversionNotFound(f"BMU version not found in the '/var/log/uboot_pm0' file on RMOD ID: {rmod_id}\n{output}")

    @log_input_and_output
    def _get_bmu_version_from_serial_logs(self, rmod_id, rsc_ops):
        """
        Gets BMU version from serial logs.

        :param rmod_id: RMOD configuration ID of radio module to connect
        :type rmod_id: str or int
        :return: BMU version e.g. '0x4_0x0_0x1'
        :rtype: str
        :raises BMUversionNotFound exception when BMU version was not found.
        """
        serial_console_file = rsc_ops.download_serial_console_log(init_radio_id=str(rmod_id))
        with open(serial_console_file, 'r') as file:
            bmu_version = None
            for line in file:
                if 'Bmu image is up to date' in line and (match := re.search(r'ver = (.*?)[)]', line)):
                    bmu_version = match.group(1)
        if bmu_version is None:
            raise BMUversionNotFound(f"BMU version not found in the serial log file: '{serial_console_file}'")
        return bmu_version
